insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Adyen$q$,$q$public_company$q$),($q$AhaMove$q$,$q$private_company$q$),($q$Be Group$q$,$q$public_company$q$),($q$Bolt$q$,$q$private_company$q$),($q$ComfortDelGro$q$,$q$public_company$q$),($q$Emtek$q$,$q$public_company$q$),($q$Everrise$q$,$q$private_company$q$),($q$Foodpanda$q$,$q$private_company$q$),($q$GXBank$q$,$q$private_company$q$),($q$Gojek$q$,$q$private_company$q$),($q$Grab PH Holdings Inc.$q$,$q$private_company$q$),($q$GrabFin Operations (Malaysia)$q$,$q$private_company$q$),($q$InDrive$q$,$q$private_company$q$),($q$Infermove$q$,$q$private_company$q$),($q$Jaya Grocer$q$,$q$private_company$q$),($q$Lalamove$q$,$q$private_company$q$),($q$Line Man Wongnai$q$,$q$private_company$q$),($q$MUFG$q$,$q$public_company$q$),($q$MUV Marketplace$q$,$q$private_company$q$),($q$Mastercard$q$,$q$public_company$q$),($q$Maxim$q$,$q$private_company$q$),($q$OVO$q$,$q$private_company$q$),($q$PT Bumi Cakrawala Perkasa$q$,$q$private_company$q$),($q$PT Solusi Pengiriman Indonesia$q$,$q$private_company$q$),($q$PT Super Bank Indonesia$q$,$q$public_company$q$),($q$Ryde$q$,$q$private_company$q$),($q$ShopeeFood$q$,$q$private_company$q$),($q$Singtel$q$,$q$public_company$q$),($q$Stash Financial$q$,$q$private_company$q$),($q$Stripe$q$,$q$private_company$q$),($q$Tada$q$,$q$private_company$q$),($q$Toyota$q$,$q$public_company$q$),($q$Transportify$q$,$q$private_company$q$),($q$Validus Capital$q$,$q$private_company$q$),($q$Vay Technology$q$,$q$private_company$q$),($q$Visa$q$,$q$public_company$q$),($q$Xanh SM$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$% equity interest in Stash Financial, Inc., a digital financial services provider in the United States.$q$),(2,$q$Both Uber and Didi could have certain competitive advantages compared to other new entrants into our markets given their familiarity with the markets, and in the case of Uber, due also to their shareholding in us and previous operations in Southeast Asia.$q$),(3,$q$Completed acquisition of Chinese AI robotics company, Infermove, which is focused on autonomous robotics for first and last-mile delivery$q$),(4,$q$Completed acquisition of a majority economic interest in Everrise$q$),(5,$q$Completed acquisition of a majority economic interest in Jaya Grocer$q$),(6,$q$Completed our 100% ownership investment in OVO$q$),(7,$q$Completed the acquisition of Uber’s business in Southeast Asia through an all-share deal following which Uber became a major strategic shareholder in Grab$q$),(8,$q$For example, in 2022, we acquired a majority economic interest in Jaya Grocer.$q$),(9,$q$Further, we own OVO and conduct our financial services businesses in Indonesia through PT Bumi Cakrawala Perkasa (“BCP”), which has a dual class share structure that gives us a 38.9% voting right while we own 82.8% of the shares in BCP.$q$),(10,$q$GXS Bank completed acquisition of Validus Capital, a digital SME lending platform in Singapore to expand our small, medium-sized enterprise lending footprint$q$),(11,$q$In 2021, we completed our 100% ownership investment in OVO.$q$),(12,$q$In 2022 and 2023, our digital banking joint venture GXS Bank and GXBank were publicly launched in Singapore and Malaysia, respectively, and are continuing to build their customer base and expand their product offerings.$q$),(13,$q$In 2022, we acquired a majority economic interest in Jaya Grocer in Malaysia.$q$),(14,$q$In 2025, we acquired a majority economic interest in Everrise, Validus Capital, a digital SME lending platform in Singapore, and Infermove, a Chinese AI robotics company.$q$),(15,$q$In 2025, we acquired a majority interest in Everrise, a premium supermarket chain that operates predominately in East Malaysia, and acquired certain assets and businesses to accelerate the growth of our financial services and AI/robotics capabilities.$q$),(16,$q$In February 2026, the Group has entered into definitive agreements to acquire $q$),(17,$q$In January 2026, the Group has acquired a minority equity interest in Vay Technology GmbH, a remote driving technology company that commercially operates in the United States, for cash consideration of $$q$),(18,$q$In May 2023, we acquired Mr. Tong's 60% interest in GOM and we now wholly own GOM.$q$),(19,$q$In addition, we conduct our point-to-point courier delivery business through PT Solusi Pengiriman Indonesia (“SPI”), in which we own 49%.$q$),(20,$q$In early 2026, we agreed to acquire Stash Financial, Inc., a digital investing platform in the U.S. (the completion of which remains subject to regulatory approvals and other customary closing conditions).$q$),(21,$q$In our deliveries segment, we face competition from regional players such as Foodpanda, ShopeeFood and Gojek (primarily in Indonesia) and single market players in Southeast Asia, including Line Man Wongnai in Thailand.$q$),(22,$q$In our mobility segment, we face competition from Gojek in Indonesia and Singapore, Be Group in Vietnam, Bolt in Thailand, Tada and Ryde in Singapore, as well as Xanh SM, Bolt, Maxim and InDrive in several Southeast Asian countries, licensed taxi operators such as ComfortDelGro in Singapore, and traditional ground transportation services, including taxi-hailing.$q$),(23,$q$Includes 865 employees of Everrise, a supermarket chainsin Malaysia, which we acquired in March 2025 and 22 employees of Infermove, an AI robotics startup in China, which we acquired in December 2025.$q$),(24,$q$On December 31, 2024, one of our wholly-owned subsidiaries, GrabCar Sdn Bhd, awarded a contract to purchase 281 units of Perodua Bezza to MUV Marketplace Sdn. Bhd. for MYR 4.7 million ($1.1 million).$q$),(25,$q$Our platform also competes with last-mile package delivery services including on-demand services such as Gojek and Lalamove, and single market players such as AhaMove in Vietnam and Transportify in the Philippines.$q$),(26,$q$PT Super Bank Indonesia Tbk, in which we have less than 50% equity interest, successfully completed its initial public offering on the Indonesia Stock Exchange$q$),(27,$q$The shares of Grab PH Holdings Inc. are 40% legal and/or beneficially owned by us, with the balance 60% of the shares held by an entity owned by our local partner, Mr. Jesse Stefan H. Maxwell, a Philippine national who is a director of certain of our Philippine operating entities, including MyTaxi.PH, Inc.$q$),(28,$q$These arrangements include joint ventures and minority equity investments, such as our Digital Banking JV with Singtel and partnerships with strategic investors such as Mitsubishi UFJ Financial Group Inc. (“MUFG”) for certain digital financial services and Toyota for certain driver-related services.$q$),(29,$q$We are party to a Framework Collaboration Agreement dated June 13, 2018 and renewed and amended on August 15, 2021, August 16, 2022 and August 1, 2023 (collectively the “FCA”) with Toyota Motor Corp. (“Toyota”), a principal shareholder.$q$),(30,$q$We conduct our point-to-point courier delivery business through PT Solusi Pengiriman Indonesia (“SPI”), in which we own 49%.$q$),(31,$q$We have also successfully pursued a strategy of making strategic alliances with suitable partners such as Singtel in Singapore and Emtek in Indonesia, and we expect to continue to do so in the future.$q$),(32,$q$We own 72.5% equity interest in Jaya Grocer that carry 50.0% voting power in Jaya Grocer outright.$q$),(33,$q$We own 82.8% of BCP, which, due to a dual-class structure, represents a 38.9% voting interest, and we also have contractual rights to (a) control the appointment of the Chief Executive Officer, and the Chief Financial Officer (including the right to nominate any such officers as directors or as president director), (b) approve the budget and business plan of BCP and its subsidiaries; (c) approve future funding of BCP and its subsidiaries, whether through debt, equity or otherwise, and (d) certain economic rights with respect to the remaining shareholding of BCP.$q$),(34,$q$We rely on strategic partnerships with financial institutions such as Visa and Mastercard and third parties such as Adyen and Stripe to process and remit payments to and from consumers and driver- and merchant-partners.$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$partners$q$,$q$GRAB$q$,$q$Singtel$q$,$q${28,31}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(2,$q$invests$q$,$q$GRAB$q$,$q$Jaya Grocer$q$,$q${32}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(3,$q$invests$q$,$q$Uber$q$,$q$GRAB$q$,$q${2,7}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(4,$q$competes$q$,$q$GRAB$q$,$q$Foodpanda$q$,$q${21}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(5,$q$competes$q$,$q$GRAB$q$,$q$ShopeeFood$q$,$q${21}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(6,$q$competes$q$,$q$GRAB$q$,$q$Gojek$q$,$q${21}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(7,$q$competes$q$,$q$GRAB$q$,$q$Line Man Wongnai$q$,$q${21}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(8,$q$competes$q$,$q$GRAB$q$,$q$Lalamove$q$,$q${25}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(9,$q$competes$q$,$q$GRAB$q$,$q$AhaMove$q$,$q${25}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(10,$q$competes$q$,$q$GRAB$q$,$q$Transportify$q$,$q${25}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(11,$q$competes$q$,$q$GRAB$q$,$q$Be Group$q$,$q${22}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(12,$q$competes$q$,$q$GRAB$q$,$q$Bolt$q$,$q${22}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(13,$q$competes$q$,$q$GRAB$q$,$q$Tada$q$,$q${22}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(14,$q$competes$q$,$q$GRAB$q$,$q$Ryde$q$,$q${22}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(15,$q$competes$q$,$q$GRAB$q$,$q$Xanh SM$q$,$q${22}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(16,$q$competes$q$,$q$GRAB$q$,$q$Maxim$q$,$q${22}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(17,$q$competes$q$,$q$GRAB$q$,$q$InDrive$q$,$q${22}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(18,$q$competes$q$,$q$GRAB$q$,$q$ComfortDelGro$q$,$q${22}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(19,$q$partners$q$,$q$GRAB$q$,$q$MUFG$q$,$q${28}$q$::int[],$q${notes